import { GameState, Ruleset, Command, PlayerView, Color, GameEvent } from '../types.js';
import { StandardChessRuleset } from './StandardChessRuleset.js';
import { Chess, Square } from 'chess.js';

export class FogOfWarRuleset implements Ruleset {
  variant = 'fog-of-war';
  private baseRules = new StandardChessRuleset();

  getInitialState(players: Partial<Record<Color, string>>): GameState {
    const state = this.baseRules.getInitialState(players);
    state.variant = this.variant;
    return state;
  }

  applyCommand(state: GameState, cmd: Command): { newState: GameState, events: GameEvent[], error?: string } {
    if (cmd.type === 'move') {
      const result = this.baseRules.applyCommand(state, cmd);
      if (result.error) {
        return { newState: state, events: [], error: 'Move blocked or illegal.' };
      }
      return result;
    }
    return { newState: state, events: [], error: 'Unknown command' };
  }

  getPlayerView(state: GameState, playerColor: Color): PlayerView {
    const chess = new Chess(state.fen);
    const viewBoard: Record<string, any> = {};
    const visibleSquares = new Set<string>();

    const board = chess.board();

    // 1. Calculate visibility
    for (let r = 0; r < 8; r++) {
      for (let c = 0; c < 8; c++) {
        const piece = board[r][c];
        if (!piece) continue;

        const sq = `${String.fromCharCode(97 + c)}${8 - r}` as Square;

        if (piece.color === playerColor) {
          // You see your own pieces
          visibleSquares.add(sq);
          viewBoard[sq] = { type: piece.type, color: piece.color };

          // You see all squares this piece can legally move to
          // Wait, chess.moves({ square }) only gives legal moves (respecting check).
          // For Dark Chess, you see pseudo-legal moves too (if pinned, you still see where the piece *could* move).
          // But for MVP, `chess.moves` is highly accurate and easiest.
          const moves = chess.moves({ square: sq, verbose: true });
          for (const move of moves) {
            visibleSquares.add(move.to);
          }

          // Pawns see their diagonal capture squares even if empty
          if (piece.type === 'p') {
            const dir = playerColor === 'w' ? 1 : -1;
            const rankObj = 8 - r + dir;
            if (rankObj >= 1 && rankObj <= 8) {
              if (c > 0) visibleSquares.add(`${String.fromCharCode(97 + c - 1)}${rankObj}`);
              if (c < 7) visibleSquares.add(`${String.fromCharCode(97 + c + 1)}${rankObj}`);
            }
          }
        }
      }
    }

    // 2. Populate the visible board with actual pieces
    for (const sq of visibleSquares) {
      // Find row/col
      const c = sq.charCodeAt(0) - 97;
      const r = 8 - parseInt(sq[1], 10);
      const piece = board[r][c];
      
      if (piece) {
        viewBoard[sq] = { type: piece.type, color: piece.color };
      } else {
        viewBoard[sq] = null; // explicitly visible but empty
      }
    }

    return {
      version: state.version,
      variant: state.variant,
      status: state.status,
      turn: state.turn,
      winner: state.winner,
      board: viewBoard, // only contains keys for visible squares
      myColor: playerColor
    };
  }
}
